CREATE TABLE IF NOT EXISTS public.rbac_platform_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),change_key text NOT NULL UNIQUE,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.rbac_platform_snapshots TO service_role;
ALTER TABLE public.rbac_platform_snapshots ENABLE ROW LEVEL SECURITY;
INSERT INTO public.rbac_platform_snapshots(change_key,snapshot) SELECT '2026-09-nine-template-and-role-reactivation',jsonb_build_object('catalogue',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.role_key),'[]') FROM public.role_catalogue c WHERE c.role_key=ANY(ARRAY['bar-manager','cashier','coffee-station-supervisor','restaurant-manager','front-office-manager','laundry-manager','hot-kitchen-supervisor','maintenance-officer','social-media-manager','reservations-agent','front-office-supervisor','front-office-cashier','driver','hr-officer','chief-steward','maintenance-technician','procurement-officer','events-coordinator','laundry-supervisor','porter','night-auditor'])),'feature_templates',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.role_key,t.module,t.feature,t.action),'[]') FROM public.role_feature_templates t WHERE t.role_key=ANY(ARRAY['bar-manager','cashier','coffee-station-supervisor','restaurant-manager','front-office-manager','laundry-manager','hot-kitchen-supervisor','maintenance-officer','social-media-manager'])),'historical_templates',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.template_key,t.module,t.action),'[]') FROM public.role_permission_templates t WHERE t.template_key=ANY(ARRAY['reservations agent','front office supervisor','front office cashier','driver','hr officer','chief steward','maintenance technician','procurement officer','events coordinator','laundry supervisor']))) ON CONFLICT(change_key) DO NOTHING;
UPDATE public.role_catalogue SET retired=false,updated_at=now() WHERE role_key=ANY(ARRAY['reservations-agent','front-office-supervisor','front-office-cashier','driver','hr-officer','chief-steward','maintenance-technician','procurement-officer','events-coordinator','laundry-supervisor']);
UPDATE public.role_catalogue SET reports_to_key='laundry-manager',reports_to_role_keys=ARRAY['laundry-manager'],updated_at=now() WHERE role_key='laundry-supervisor';
UPDATE public.role_catalogue SET retired=true,updated_at=now() WHERE role_key IN('porter','night-auditor');
UPDATE public.role_catalogue SET reports_to_role_keys=array_remove(coalesce(reports_to_role_keys,'{}'),'night-auditor'),can_manage_role_keys=array_remove(coalesce(can_manage_role_keys,'{}'),'night-auditor'),updated_at=now() WHERE 'night-auditor'=ANY(coalesce(reports_to_role_keys,'{}')) OR 'night-auditor'=ANY(coalesce(can_manage_role_keys,'{}'));
CREATE OR REPLACE FUNCTION public.neo_role_is_staffed(_role uuid,_branch uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='public' AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles ur JOIN public.profiles p ON p.id=ur.user_id WHERE ur.role_id=_role AND p.organization_id=public.current_org_id() AND coalesce(p.account_status,'active')='active' AND (_branch IS NULL OR p.branch_id=_branch OR EXISTS(SELECT 1 FROM public.employee_branch_assignments e WHERE e.employee_id=p.id AND e.organization_id=p.organization_id AND e.branch_id=_branch AND e.effective_from<=current_date AND(e.effective_to IS NULL OR e.effective_to>=current_date)))) $$;
REVOKE ALL ON FUNCTION public.neo_role_is_staffed(uuid,uuid) FROM public,anon; GRANT EXECUTE ON FUNCTION public.neo_role_is_staffed(uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.neo_approval_route(_type text,_amount numeric DEFAULT NULL,_percent numeric DEFAULT NULL,_branch uuid DEFAULT NULL,_department uuid DEFAULT NULL,_requester uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='public' AS $$ DECLARE o uuid:=public.current_org_id();q uuid:=coalesce(_requester,auth.uid());x record;ops uuid;own uuid;unstaffed boolean:=false;reserved boolean; BEGIN IF o IS NULL THEN RETURN jsonb_build_object('status','unconfigured','message','No workspace context'); END IF; reserved:=lower(coalesce(_type,''))=ANY(ARRAY['void','cancel','cancellation','discount','refund','complimentary','rate-override','write-off','payment-reversal','till-reopen','period-reopen']); IF reserved THEN SELECT id INTO own FROM public.roles WHERE organization_id=o AND coalesce(active,true) AND public.neo_resolve_role_template_key(normalized_role_key,name)='owner' AND public.neo_role_is_staffed(id,_branch) LIMIT 1; IF own IS NULL THEN RETURN jsonb_build_object('status','owner_unstaffed','message','This Owner-reserved action has no staffed Owner approver.'); END IF; RETURN jsonb_build_object('status','owner_reserved','level',1,'approver_role_id',own,'approver_user_id',NULL,'required_approvers',1,'message','Routed to Owner under restricted-action policy.'); END IF; FOR x IN SELECT * FROM public.approval_rules r WHERE r.organization_id=o AND r.active AND r.approval_type=_type AND(r.branch_id IS NULL OR r.branch_id=_branch) AND(r.department_id IS NULL OR r.department_id=_department) ORDER BY(r.branch_id IS NOT NULL)DESC,(r.department_id IS NOT NULL)DESC,r.level LOOP IF(x.max_amount IS NOT NULL AND _amount IS NOT NULL AND _amount>x.max_amount)OR(x.max_percent IS NOT NULL AND _percent IS NOT NULL AND _percent>x.max_percent)THEN CONTINUE; END IF; IF x.approver_user_id=q AND NOT x.allow_self_approval THEN CONTINUE; END IF; IF x.approver_user_id IS NULL AND x.approver_role_id IS NOT NULL AND NOT public.neo_role_is_staffed(x.approver_role_id,_branch) THEN unstaffed:=true;CONTINUE; END IF; RETURN jsonb_build_object('status','ok','rule_id',x.id,'level',x.level,'approver_role_id',x.approver_role_id,'approver_user_id',x.approver_user_id,'required_approvers',x.required_approvers,'message','Routed to the configured approver.'); END LOOP; IF unstaffed THEN SELECT id INTO ops FROM public.roles WHERE organization_id=o AND coalesce(active,true) AND public.neo_resolve_role_template_key(normalized_role_key,name)='operations-manager' AND public.neo_role_is_staffed(id,_branch) LIMIT 1; IF ops IS NOT NULL THEN RETURN jsonb_build_object('status','delegated','level',1,'approver_role_id',ops,'approver_user_id',NULL,'required_approvers',1,'message','Configured departmental approver unavailable; routed to Operations Manager for this request only.'); END IF; RETURN jsonb_build_object('status','unstaffed','message','No staffed departmental approver or Operations Manager is available for this property.'); END IF; RETURN jsonb_build_object('status','unconfigured','message','No approval authority is configured for this request type and scope.'); END $$;
REVOKE ALL ON FUNCTION public.neo_approval_route(text,numeric,numeric,uuid,uuid,uuid) FROM public,anon; GRANT EXECUTE ON FUNCTION public.neo_approval_route(text,numeric,numeric,uuid,uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.neo_approval_seed_steps() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE route jsonb;s text;rr uuid;ru uuid;l int; BEGIN IF NEW.status<>'pending_approval' THEN RETURN NEW; END IF; route:=public.neo_approval_route(NEW.approval_type,NEW.amount,NEW.requested_percent,NEW.branch_id,NEW.department_id,NEW.requester_id);s:=route->>'status'; IF s=ANY(ARRAY['ok','delegated','owner_reserved']) THEN rr:=nullif(route->>'approver_role_id','')::uuid;ru:=nullif(route->>'approver_user_id','')::uuid;l:=greatest(coalesce((route->>'level')::int,1),1);INSERT INTO public.approval_steps(organization_id,request_id,level,status,activated_at,approver_user_id,approver_role_id,rule_id)VALUES(NEW.organization_id,NEW.id,l,'active',now(),ru,rr,nullif(route->>'rule_id','')::uuid)ON CONFLICT(request_id,level)DO NOTHING;UPDATE public.approval_requests SET level=l,max_level=greatest(coalesce(max_level,1),l),approver_id=ru WHERE id=NEW.id; ELSE INSERT INTO public.audit_logs(organization_id,user_id,user_name,action,module,record_id,new_value,reason)VALUES(NEW.organization_id,NEW.requester_id,'','approval.routing.blocked','governance',NEW.id::text,route,coalesce(route->>'message','Approval routing unavailable')); END IF; INSERT INTO public.audit_logs(organization_id,user_id,user_name,action,module,record_id,new_value)VALUES(NEW.organization_id,NEW.requester_id,'','approval.routed','governance',NEW.id::text,route);RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.neo_delete_structure_record(_kind text,_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE o uuid:=public.current_org_id();n text;c int;b jsonb:='[]'; BEGIN IF o IS NULL OR NOT public.neo_can_manage_roles() THEN RAISE EXCEPTION 'Not authorised to delete organisation structure'; END IF; IF _kind='role' THEN SELECT name INTO n FROM public.roles WHERE id=_id AND organization_id=o FOR UPDATE;IF n IS NULL THEN RAISE EXCEPTION 'Role not found';END IF;SELECT count(*)INTO c FROM public.user_roles WHERE role_id=_id;IF c>0 THEN b:=b||jsonb_build_array(jsonb_build_object('table','staff assignments','column','role','rows',c));END IF;SELECT count(*)INTO c FROM public.approval_rules WHERE approver_role_id=_id;IF c>0 THEN b:=b||jsonb_build_array(jsonb_build_object('table','approval rules','column','approver role','rows',c));END IF;SELECT count(*)INTO c FROM public.role_catalogue WHERE reports_to_key=(SELECT normalized_role_key FROM public.roles WHERE id=_id);IF c>0 THEN b:=b||jsonb_build_array(jsonb_build_object('table','current role hierarchy','column','reports to','rows',c));END IF;IF jsonb_array_length(b)>0 THEN RETURN jsonb_build_object('ok',false,'deleted',false,'blockers',b);END IF;DELETE FROM public.role_dashboard_assignments WHERE role_id=_id;DELETE FROM public.role_permissions WHERE role_id=_id;DELETE FROM public.roles WHERE id=_id AND organization_id=o; ELSIF _kind='department' THEN SELECT name INTO n FROM public.departments WHERE id=_id AND organization_id=o FOR UPDATE;IF n IS NULL THEN RAISE EXCEPTION 'Department not found';END IF;SELECT count(*)INTO c FROM public.profiles WHERE department_id=_id;IF c>0 THEN b:=b||jsonb_build_array(jsonb_build_object('table','staff records','column','department','rows',c));END IF;SELECT count(*)INTO c FROM public.roles WHERE department_id=_id;IF c>0 THEN b:=b||jsonb_build_array(jsonb_build_object('table','roles','column','department','rows',c));END IF;SELECT count(*)INTO c FROM public.approval_rules WHERE department_id=_id;IF c>0 THEN b:=b||jsonb_build_array(jsonb_build_object('table','approval rules','column','department','rows',c));END IF;IF jsonb_array_length(b)>0 THEN RETURN jsonb_build_object('ok',false,'deleted',false,'blockers',b);END IF;DELETE FROM public.departments WHERE id=_id AND organization_id=o;ELSE RAISE EXCEPTION 'Unsupported structure kind';END IF;INSERT INTO public.audit_logs(organization_id,user_id,user_name,action,module,record_id,new_value)VALUES(o,auth.uid(),coalesce((SELECT full_name FROM public.profiles WHERE id=auth.uid()),''),'structure.deleted','administration',_id::text,jsonb_build_object('kind',_kind,'name',n));RETURN jsonb_build_object('ok',true,'deleted',true,'blockers','[]','name',n);END $$;
REVOKE ALL ON FUNCTION public.neo_delete_structure_record(text,uuid) FROM public,anon;GRANT EXECUTE ON FUNCTION public.neo_delete_structure_record(text,uuid) TO authenticated,service_role;